-- BEGIN BUNDLED LIBRARIES (tools/bundle_libs.py)
-- Generated by tools/bundle_libs.py — do not edit by hand. Regenerate with: python3 tools/bundle_libs.py
local __LIBS = {}
local __LOADERS = {}
-- Forward declaration: libraries call require_lib at load time.
local require_lib

__LOADERS["catalog"] = function(...)
-- =====================================================================
-- Lib: catalog/pagination helpers for plugin catalogs: hasNextPage,
--      nextIndex/pageUrl (dominant "?page=N" scheme), urlEncode.
-- Loaded via require_lib("catalog"). No dependencies on other libs.
-- =====================================================================
local version = "1.0.1"

local M = {}

-- =====================================================================
-- Pagination
-- =====================================================================

-- "Has next page" for the dominant scheme where a page is considered
-- non-final as long as it returned any item (39 inline copies of
-- `#items > 0`, plus 7 local hasNextPage helpers with the same body).
-- Plugins that know their total page count keep their own comparison.
function M.hasNextPage(items)
    return type(items) == "table" and #items > 0
end

-- Catalog index is 0-based; pages on the wire are 1-based — the
-- dominant `local page = index + 1` from 74 plugins.
function M.nextIndex(index)
    return (index or 0) + 1
end

-- Build a page URL from a template with "{n}" where the 1-based page
-- number goes. Matches the dominant string-concat schemes:
--   ".../catalog?page={n}"        (guide, most sites)
--   "...&pg={n}"                  (en/scribblehub.lua:33)
--   "...&bpage={n}"               (ru/bookhamster.lua:85)
-- Sites with conditional page params or API cursors keep their own code.
function M.pageUrl(template, index)
    return (template:gsub("{n}", tostring(M.nextIndex(index))))
end

-- =====================================================================
-- Query encoding
-- =====================================================================

-- Pure-Lua mirror of the engine global url_encode (Java
-- URLEncoder.encode(s, "UTF-8"): application/x-www-form-urlencoded —
-- space -> "+", unreserved A-Za-z0-9 . - * _ kept, everything else
-- "%XX" uppercase over UTF-8 bytes, "\n" normalized to "\r\n" first).
-- The 73 plugin call sites use the engine global directly; this copy
-- exists for shared libs and parity tests outside the engine.
-- Byte-wise whitelist: LuaJ's %w matches Latin-1 letters (0xC0-0xFF), so a
-- UTF-8 byte like 0xE3 would stay raw and corrupt the query (CJK/Cyrillic
-- search returned 0). Java URLEncoder keeps only A-Z a-z 0-9 . - * _.
local function unreserved(b)
    return (b >= 48 and b <= 57)
        or (b >= 65 and b <= 90)
        or (b >= 97 and b <= 122)
        or b == 45 or b == 46 or b == 42 or b == 95
end

function M.urlEncode(s)
    if type(s) ~= "string" then return s end
    s = s:gsub("\n", "\r\n")
    return (s:gsub(".", function(c)
        local b = string.byte(c)
        if b == 32 then return "+" end
        if unreserved(b) then return c end
        return string.format("%%%02X", b)
    end))
end

return M
end

__LOADERS["fetch"] = function(...)
-- =====================================================================
-- Lib: session-cached page fetch. The engine calls getBookTitle /
-- getBookCoverImageUrl / getBookDescription / getBookGenres /
-- getBookStatus / getBookLastUpdate in parallel, each doing its own
-- http_get(bookUrl) — this module keeps one request per URL.
-- Loaded via require_lib("fetch"). No dependencies on other libs.
--
-- Same contract as the inline fetchPage copies (guide:643):
--   * cache lives for the session only, never for getChapterListHash —
--     that one must always use a direct http_get;
--   * only successful responses are cached, a failed call returns nil
--     and the next call retries;
--   * the cache key is the URL. A non-empty `config` that changes the
--     response body (headers, charset, ...) becomes part of the key, so
--     two configs never share a body.
-- =====================================================================
local version = "1.0.0"

local M = {}

local cache = {}

local function logErr(msg)
    if type(log_error) == "function" then log_error(msg) end
end

-- Order-independent encoding of a config table, so {a=1,b=2} and {b=2,a=1}
-- share one cache entry. Cycles are not possible here: http_get configs are
-- plain string/number/bool values and one level of headers table.
local function encode(value)
    local t = type(value)
    if t == "table" then
        local keys = {}
        for k in pairs(value) do keys[#keys + 1] = k end
        table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
        local parts = {}
        for _, k in ipairs(keys) do
            parts[#parts + 1] = tostring(k) .. "=" .. encode(value[k])
        end
        return "{" .. table.concat(parts, ";") .. "}"
    end
    return tostring(value)
end

local function keyOf(url, config)
    if type(config) ~= "table" then return url end
    local keys = {}
    for k in pairs(config) do keys[#keys + 1] = k end
    if #keys == 0 then return url end
    table.sort(keys, function(a, b) return tostring(a) < tostring(b) end)
    local parts = {}
    for _, k in ipairs(keys) do
        parts[#parts + 1] = tostring(k) .. "=" .. encode(config[k])
    end
    return url .. "\0" .. table.concat(parts, ";")
end

-- GET `url` (optional http_get `config`) -> response body or nil.
-- ponytail: no TTL — the plugin session is short-lived and every copy in
-- the repo caches for the whole session (only mtl/wtrlab.lua adds a TTL);
-- add one when a caller actually needs staleness control.
function M.page(url, config)
    if type(url) ~= "string" or url == "" then return nil end
    local key = keyOf(url, config)
    local cached = cache[key]
    if cached ~= nil then return cached end
    local r = http_get(url, config)
    if type(r) ~= "table" or not r.success then
        logErr("fetch: GET failed (HTTP " .. tostring(r and r.code) .. ") " .. url)
        return nil
    end
    cache[key] = r.body
    return r.body
end

-- Drop the whole session cache, or every entry of one URL when given
-- (all config variants of that URL).
function M.clear(url)
    if url == nil then
        cache = {}
        return
    end
    local prefix = url .. "\0"
    for key in pairs(cache) do
        if key == url or key:sub(1, #prefix) == prefix then cache[key] = nil end
    end
end

return M
end

__LOADERS["hls"] = function(...)
-- =====================================================================
-- Lib: stream helpers for videohost extractors: pickStream (generic
--      m3u8/mp4 scan) + hasMediaExt (mime typing of extension-less URLs).
-- Loaded via require_lib("hls"); uses require_lib("urls").
-- =====================================================================
local version = "1.0.0"

local urls = require_lib("urls")

local M = {}

-- =====================================================================
-- Generic stream scan
-- =====================================================================

function M.pickStream(t, embedUrl)
    -- 1) absolute URL
    local hls = t:match([=[(https?://[^"'%s\<>]+%.m3u8[^"'%s\<>]*)]=])
    if hls then return hls, "hls" end

    -- 2) quoted, relative or protocol-relative
    for _, q in ipairs({ '"', "'" }) do
        for s in t:gmatch(q .. "([^" .. q .. "\r\n]+)" .. q) do
            if #s < 600 and not s:find("%s") and s:lower():find(".m3u8", 1, true) then
                return urls.resolve(s, embedUrl), "hls"
            end
        end
    end

    -- 3) direct mp4
    local mp4 = t:match([=[(https?://[^"'%s\<>]+%.mp4[^"'%s\<>]*)]=])
    if mp4 then return mp4, "mp4" end
    for _, q in ipairs({ '"', "'" }) do
        for s in t:gmatch(q .. "(//[^" .. q .. "\r\n]+)" .. q) do
            if #s < 600 and not s:find("%s") and s:lower():find(".mp4", 1, true) then
                return urls.resolve(s, embedUrl), "mp4"
            end
        end
    end
    return nil, nil
end

-- =====================================================================
-- Media extension check
-- =====================================================================

-- Does the URL path (before "?" / "#") end with a media extension?
-- Without it media3 types the stream as progressive and fails on an HLS
-- body (rationale: ar/anime4up.lua:328). Union of the three plugin copies
-- (ar/anime4up.lua:330, ar/animephoenix.lua:45, ar/witanime.lua:1958):
-- .mkv comes from animephoenix and is progressive too, so it must not be
-- typed as "hls".
function M.hasMediaExt(u)
    local base = u:match("^[^%?#]*") or u
    return base:match("%.m3u8$") ~= nil
        or base:match("%.mp4$") ~= nil
        or base:match("%.mkv$") ~= nil
end

return M
end

__LOADERS["mp4upload"] = function(...)
-- =====================================================================
-- Lib: mp4upload
-- Loaded via require_lib("mp4upload"). No dependencies on other libs.
-- =====================================================================
local M = {}

function M.extractMp4upload(both)
    local u = both:match('player%.src%(%s*"([^"]+)"')
        or both:match('player%.src%(%s*{.-src%s*:%s*"([^"]+)"')
        or both:match('src%s*:%s*"(https?://[^"]+%.mp4[^"]*)"')
    if u then return u, "mp4", "https://www.mp4upload.com/" end
    return nil
end

return M
end

__LOADERS["pixeldrain"] = function(...)
-- =====================================================================
-- Lib: pixeldrain — /u/<id> (or /api/file/<id>) embed link -> direct
-- https://pixeldrain.com/api/file/<id> mp4 (the site serves the file
-- without Referer/cookies).
-- Extracted from es/hentaila.lua:259-265 (the pdrain branch of
-- resolveEmbed).
-- Loaded via require_lib("pixeldrain"). No dependencies on other libs.
-- No HTTP: the file URL is a deterministic mapping of the embed link.
-- =====================================================================
local version = "1.0.0"

local M = {}

-- server — имя сервера из разметки сайта, url — ссылка эмбеда.
-- Контракт двух возвратов:
--   src, true  — это pixeldrain: src = { url, mime = "mp4" } или nil, если
--                id файла не распознан — ветка эмбеда коротко замыкается,
--                фоллбэки других хостеров НЕ применяются (как в оригинале);
--   nil, false — не pixeldrain, продолжаем разбор.
function M.resolve(server, url)
    if type(url) ~= "string" then return nil, false end
    local lower = type(server) == "string" and server:lower() or ""
    if lower ~= "pdrain" and not url:find("pixeldrain", 1, true) then
        return nil, false
    end
    local fileId = url:match("/u/([%w_%-]+)") or url:match("/api/file/([%w_%-]+)")
    if not fileId then return nil, true end
    return { url = "https://pixeldrain.com/api/file/" .. fileId, mime = "mp4" }, true
end

return M
end

__LOADERS["urls"] = function(...)
-- =====================================================================
-- Lib: shared URL helpers (origin, unescapeSlashes, hostOf, resolve,
--      absUrl, driveDirectUrl) for videohost and novel extractors.
-- Loaded via require_lib("urls"). No dependencies on other libs.
-- =====================================================================
local version = "1.2.0"

local M = {}

-- =====================================================================
-- URL helpers
-- =====================================================================

function M.origin(url)
    local scheme, host = url:match("^(https?)://([^/?#]+)")
    if not scheme then return nil end
    return scheme .. "://" .. host .. "/"
end

function M.unescapeSlashes(s)
    local r = s:gsub("\\/", "/")
    r = r:gsub("\\u0026", "&")
    return r
end

function M.hostOf(url)
    return ((url or ""):match("^https?://([^/?#:]+)") or ""):lower()
end

-- Relative / protocol-relative URL -> absolute (relative to the embed).
function M.resolve(u, embedUrl)
    u = M.unescapeSlashes(u)
    if u:sub(1, 2) == "//" then return "https:" .. u end
    if u:find("^https?://") then return u end
    local o = M.origin(embedUrl or "")
    if o then
        o = o:gsub("/$", "")
        return o .. (u:sub(1, 1) == "/" and u or ("/" .. u))
    end
    return u
end

-- RFC 3986 merge, mirroring java.net.URI(base):resolve(href) — the exact
-- semantics of the engine global url_resolve (plugin-tester-jvm
-- LuaEngineCli.kt:355). Used only when that global is unavailable
-- (offline tests); in the app the global always wins.
local function removeDotSegments(p)
    local leading = p:sub(1, 1) == "/"
    local segs = {}
    for seg in p:gmatch("[^/]+") do
        if seg == ".." then
            if #segs > 0 and segs[#segs] ~= ".." then
                segs[#segs] = nil
            elseif not leading then
                segs[#segs + 1] = seg
            end
        elseif seg ~= "." then
            segs[#segs + 1] = seg
        end
    end
    local out = table.concat(segs, "/")
    if leading then out = "/" .. out end
    if p:sub(-1) == "/" and out:sub(-1) ~= "/" then out = out .. "/" end
    return out
end

local function splitRef(u)
    local path, query, fragment = u, "", ""
    local hash = path:find("#", 1, true)
    if hash then fragment = path:sub(hash + 1) path = path:sub(1, hash - 1) end
    local qm = path:find("?", 1, true)
    if qm then query = path:sub(qm + 1) path = path:sub(1, qm - 1) end
    return path, query, fragment
end

local function resolveRef(base, ref)
    if type(base) ~= "string" or type(ref) ~= "string" then return ref end
    if ref:match("^%a[%w+.-]*:") then return ref end
    local scheme, authority, rest = base:match("^(%a[%w+.-]*)://([^/?#]*)(.*)$")
    if not scheme then return ref end
    if ref:sub(1, 2) == "//" then return scheme .. "://" .. ref:sub(3) end
    local rPath, rQuery, rFrag = splitRef(ref)
    local bPath, bQuery = splitRef(rest)
    local path, query
    if rPath == "" then
        path = bPath
        query = (rQuery ~= "") and rQuery or bQuery
    elseif rPath:sub(1, 1) == "/" then
        path = rPath
        query = rQuery
    else
        path = (bPath:match("^.*/") or "/") .. rPath
        query = rQuery
    end
    local out = scheme .. "://" .. authority .. removeDotSegments(path)
    if query ~= "" then out = out .. "?" .. query end
    if rFrag ~= "" then out = out .. "#" .. rFrag end
    return out
end

-- href found in a page -> absolute URL, relative to `base` (usually baseUrl).
-- Union of the two inline variants: the dominant url_resolve one (guide:1763,
-- 36 byte-identical copies, e.g. ru/ranobehub.lua:11) and the manual sub/find
-- one (es/latanime.lua:94, en/hianimes.lua:50, id/anichin.lua:70). They agree
-- on absolute / protocol-relative / root-relative hrefs; for a bare relative
-- href the canonical url_resolve merge (RFC 3986) is used, the manual copies
-- joined it as baseDir .. "/" .. href — plugins relying on that join must be
-- checked during migration. Empty or non-string href -> "" (guide template).
function M.absUrl(base, href)
    if type(href) ~= "string" or href == "" then return "" end
    if href:sub(1, 4) == "http" then return href end
    if href:sub(1, 2) == "//" then return "https:" .. href end
    if type(url_resolve) == "function" then return url_resolve(base, href) end
    return resolveRef(base, href)
end

-- Google Drive file page -> direct usercontent download URL, no network:
-- the file id lives in the link itself (checked live 2026-10-03, usercontent
-- with confirm=t answers 206 without a single header).
-- Merged from the four inline copies: ar/anime4up.lua:813, ar/witanime.lua:1423,
-- ar/animephoenix.lua:698, es/latanime.lua:280 — all equivalent; the union keeps
-- the nil-safe host match (anime4up dereferenced match() without `or ""`).
-- ponytail: no playback-API fallback for "download disabled" (403 + UA binding) —
-- add it when locked links actually show up on the sites.
function M.driveDirectUrl(link)
    if type(link) ~= "string" then return nil end
    local host = (link:match("^https?://([^/]+)") or ""):lower()
    host = host:gsub("^www%.", "")
    if host ~= "drive.google.com" and host ~= "drive.usercontent.google.com" then
        return nil
    end
    local id = link:match("/file/d/([%w_-]+)") or link:match("[?&]id=([%w_-]+)")
    if not id then return nil end
    local u = "https://drive.usercontent.google.com/download?id=" .. id
        .. "&export=download&confirm=t"
    local rk = link:match("[?&]resourcekey=([%w_-]+)")
    if rk then u = u .. "&resourcekey=" .. rk end
    return u
end

return M
end

require_lib = function(id)
    local cached = rawget(__LIBS, id)
    if cached ~= nil then return cached end
    local loader = rawget(__LOADERS, id)
    if loader == nil then error("bundle_libs: unknown library id: " .. tostring(id), 2) end
    local value = loader()
    __LIBS[id] = value
    return value
end
-- END BUNDLED LIBRARIES (tools/bundle_libs.py)
-- Hentaila — video plugin for Dreamora (content_type = "video")
-- Ported from the CloudStream extension Hentaila.kt (selectors + embed parsing).
-- NOT tested against the live site: adjust selectors if the layout changed.

id           = "hentaila"
name         = "Hentaila"
version      = "1.1.1"
baseUrl      = "https://hentaila.com"
language = {"es", "en"}
content_type = "video"
icon         = "https://raw.githubusercontent.com/Stlucifer15t/external-sources/refs/heads/main/icons/hentaila.png"

-- ── Guard: old app builds without require_lib ────────────────────────────────
-- Top-level must load without require_lib (otherwise the plugin silently
-- disappears from the sources list) — pcall-tryLib pattern (latanime M9):
-- the error is kept in libErr and reported from ensureLibs.
local libErr = nil
local HAS_LIBS = type(require_lib) == "function"

local function tryLib(name)
    if not HAS_LIBS then return nil end
    local ok, res = pcall(require_lib, name)
    if not ok then libErr = tostring(res) return nil end
    return res
end

local MP4UPLOAD = tryLib("mp4upload")
local PIXELDRAIN = tryLib("pixeldrain")
local FETCH = tryLib("fetch")
local URLS = tryLib("urls")
local CATLIB = tryLib("catalog")

-- User-facing strings stay in Spanish (plugin language = {"es", "en"}), like
-- es/latanime.lua. show_error is async in production, hence error(..., 0).
local function ensureLibs()
    if not HAS_LIBS then
        show_error("Se requiere actualizar Dreamora", "Este complemento usa bibliotecas comunes (require_lib). Actualice la aplicación a la última versión.")
        error("Se requiere la última versión de la aplicación (require_lib)", 0)
    end
    if not MP4UPLOAD or not PIXELDRAIN or not FETCH or not URLS or not CATLIB then
        show_error("Bibliotecas no cargadas", "Abra la pantalla de extensiones y pulse actualizar; después reinicie la aplicación. " .. (libErr or ""))
        error("Bibliotecas comunes no cargadas", 0)
    end
end

local CATALOG = baseUrl .. "/catalogo"
-- Same selector as the Kotlin source; "\\/" is the escaped slash in "group/item".
local CARD_SEL = "div.grid.grid-cols-2 article.group\\/item"

-- ── Helpers ───────────────────────────────────────────────────────────────────

local function absUrl(href) return URLS.absUrl(baseUrl, href) end

-- Episode URLs look like /media/<slug>/<n>; the book URL is /media/<slug>.
local function bookUrlOf(url)
    return url:match("^(.-/media/[^/?#]+)") or url
end

-- Session cache lives in the shared fetch lib (it also logs failures).
local function fetchPage(url) return FETCH.page(url) end

local function parseCards(body)
    local items = {}
    for _, card in ipairs(html_select(body, CARD_SEL)) do
        local title = ""
        local h3 = html_select_first(card.html, "h3")
        if h3 then title = string_clean(h3.text) end
        if title == "" then
            local sr = html_select_first(card.html, "span.sr-only")
            if sr then title = string_clean(sr.text) end
        end
        local a = html_select_first(card.html, "a")
        if title ~= "" and a and a.href ~= "" then
            table.insert(items, {
                title = title,
                url   = bookUrlOf(absUrl(a.href)),
                cover = absUrl(html_attr(card.html, "img", "src"))
            })
        end
    end
    return items
end

local function fetchCatalog(query)
    local r = http_get(CATALOG .. query)
    if not r.success then
        log_error("Hentaila: catalog failed (HTTP " .. tostring(r.code) .. ")")
        return { items = {}, hasNext = false }
    end
    local items = parseCards(r.body)
    return { items = items, hasNext = CATLIB.hasNextPage(items) }
end

-- ── Catalog / search ──────────────────────────────────────────────────────────

function getCatalogList(index)
    ensureLibs()
    return fetchCatalog("?order=latest_added&page=" .. CATLIB.nextIndex(index))
end

function getCatalogSearch(index, query)
    ensureLibs()
    if not query or query == "" then return { items = {}, hasNext = false } end
    return fetchCatalog("?search=" .. CATLIB.urlEncode(query) .. "&page=" .. CATLIB.nextIndex(index))
end

-- ── Book details ──────────────────────────────────────────────────────────────

function getBookTitle(bookUrl)
    ensureLibs()
    local body = fetchPage(bookUrl)
    if not body then return nil end
    local el = html_select_first(body, "h1")
    return el and string_clean(el.text) or nil
end

function getBookCoverImageUrl(bookUrl)
    ensureLibs()
    local body = fetchPage(bookUrl)
    if not body then return nil end
    local cover = html_attr(body, "img.aspect-poster", "src")
    return cover ~= "" and absUrl(cover) or nil
end

function getBookDescription(bookUrl)
    ensureLibs()
    local body = fetchPage(bookUrl)
    if not body then return nil end
    local el = html_select_first(body, "div.entry.text-lead p")
    return el and string_trim(el.text) or nil
end

function getBookGenres(bookUrl)
    ensureLibs()
    local body = fetchPage(bookUrl)
    if not body then return {} end

    local function collect(selector)
        local genres, seen = {}, {}
        for _, a in ipairs(html_select(body, selector)) do
            local g = string_clean(a.text)
            if g ~= "" and not seen[g:lower()] then
                seen[g:lower()] = true
                table.insert(genres, g)
            end
        end
        return genres
    end

    -- Same container as the CloudStream source, then looser fallbacks.
    local genres = collect('div.flex-wrap.gap-2 a[href*="genre="]')
    if #genres == 0 then genres = collect('main a[href*="genre="]') end
    if #genres == 0 then genres = collect('a[href*="catalogo?genre"]') end
    if #genres == 0 then
        log_error("Hentaila: no genres found for " .. bookUrl)
    end
    return genres
end

-- ── Episodes ──────────────────────────────────────────────────────────────────

local function loadEpisodes(bookUrl)
    -- Direct request (not cached): chapters are parsed from the book page HTML.
    local r = http_get(bookUrl)
    if not r.success then
        log_error("Hentaila: episodes failed (HTTP " .. tostring(r.code) .. ")")
        return {}
    end

    local list, seen, allNumbered = {}, {}, true
    for _, ep in ipairs(html_select(r.body, CARD_SEL)) do
        local a = html_select_first(ep.html, "a")
        if a and a.href ~= "" then
            local url = absUrl(a.href)
            if not seen[url] then
                seen[url] = true
                local numEl = html_select_first(ep.html, "div.bg-line span")
                local num = numEl and tonumber(string_trim(numEl.text)) or nil
                if not num then allNumbered = false end
                local nameEl = html_select_first(ep.html, "div.bg-line")
                local title = nameEl and string_clean(nameEl.text) or ""
                if title == "" then
                    title = "Episodio " .. tostring(num or (#list + 1))
                end
                table.insert(list, { title = title, url = url, num = num })
            end
        end
    end

    -- Engine expects oldest → newest.
    if allNumbered then
        table.sort(list, function(x, y) return x.num < y.num end)
    end

    local chapters = {}
    for _, ep in ipairs(list) do
        table.insert(chapters, { title = ep.title, url = ep.url })
    end
    return chapters
end

function getChapterList(bookUrl)
    ensureLibs()
    return loadEpisodes(bookUrl)
end

function getChapterListHash(bookUrl)
    ensureLibs()
    local chapters = loadEpisodes(bookUrl)
    if #chapters == 0 then return nil end
    return tostring(#chapters) .. "|" .. chapters[#chapters].url
end

-- ── Video resolution ──────────────────────────────────────────────────────────

local function origin(url) return URLS.origin(url) end

-- Best-effort extraction of a direct stream from an embed page.
local function scanEmbedPage(embedUrl)
    local r = http_get(embedUrl)
    if not r.success then return nil, nil end
    local body = r.body:gsub("\\/", "/")
    local hls = body:match('(https?://[^"\'%s\\]+%.m3u8[^"\'%s\\]*)')
    if hls then return hls, "hls" end
    local mp4 = body:match('src:%s*"(https?://[^"]+%.mp4[^"]*)"')
        or body:match('(https?://[^"\'%s\\]+%.mp4[^"\'%s\\]*)')
    if mp4 then return mp4, "mp4" end
    return nil, nil
end

-- Maps one embed entry to a playable source, or nil.
local function resolveEmbed(server, url)
    local lower = server:lower()

    -- Internal CDN: /play/ is the player page, /m3u8/ is the playlist.
    if url:find("cdn.hvidserv.com/play/", 1, true) then
        return {
            url     = url:gsub("/play/", "/m3u8/"),
            mime    = "hls",
            headers = { ["sec-fetch-site"] = "same-origin" },
        }
    end

    -- PixelDrain: /u/<id> page → /api/file/<id> direct file (lib pixeldrain).
    -- Второй возврат resolve — «это pixeldrain»: при нераспознанном id ветка
    -- коротко замыкается в nil, фоллбэки ниже не применяются.
    local pdrain, isPdrain = PIXELDRAIN.resolve(server, url)
    if isPdrain then return pdrain end

    -- MP4Upload: needs the embed page's Referer; file URL comes from
    -- player.src inside the page (lib mp4upload).
    if lower == "mp4upload" or url:find("mp4upload", 1, true) then
        local r = http_get(url)
        if not r.success then return nil end
        local u, mime, ref = MP4UPLOAD.extractMp4upload(r.body:gsub("\\/", "/"))
        if u then
            return { url = u, mime = mime, headers = { ["Referer"] = ref } }
        end
        return nil
    end

    -- HLS / unknown servers: direct playlist, or scan the embed page.
    if url:find("%.m3u8") then
        return { url = url, mime = "hls", headers = origin(url) and { ["Referer"] = origin(url) } or nil }
    end
    local stream, mime = scanEmbedPage(url)
    if stream then
        local src = { url = stream, mime = mime }
        local ref = origin(url)
        if ref then src.headers = { ["Referer"] = ref } end
        return src
    end
    return nil
end

function getVideoList(episodeUrl)
    ensureLibs()
    local r = http_get(episodeUrl)
    if not r.success then
        log_error("Hentaila: episode page failed (HTTP " .. tostring(r.code) .. ")")
        return {}
    end

    -- Embeds are serialized inside the SvelteKit bootstrap script:
    --   embeds:{DUB:[{server:"X",url:"Y"},...],SUB:[...]},downloads
    local embeds = r.body:match("embeds:{(.-)},downloads")
    if not embeds then
        log_error("Hentaila: embeds block not found in " .. episodeUrl)
        return {}
    end
    embeds = embeds:gsub("\\/", "/")

    local sources, seen = {}, {}
    for _, track in ipairs({ "SUB", "DUB" }) do
        local list = embeds:match(track .. ":%[(.-)%]")
        if list then
            for server, url in list:gmatch('{server:"([^"]+)",%s*url:"([^"]+)"') do
                if not seen[url] then
                    seen[url] = true
                    local src = resolveEmbed(server, url)
                    if src then
                        src.quality = track .. " · " .. server
                        table.insert(sources, src)
                    else
                        log_info("Hentaila: skipped " .. track .. " " .. server .. " " .. url)
                    end
                end
            end
        end
    end

    return sources
end

-- ── Filters ───────────────────────────────────────────────────────────────────
-- The site expects LOWERCASE genre slugs (the CloudStream source calls
-- .lowercase() on them), e.g. ?genre=casadas or ?genre=juegos sexuales.

-- Genres the site's UI exposes that we never list (sexualised minors).
local BLOCKED_GENRES = { loli = true, lolicon = true }

-- Fallback list, used when discovery from the site finds nothing.
local STATIC_GENRES = {
    { "casadas", "Casadas" }, { "ahegao", "Ahegao" }, { "chikan", "Chikan" },
    { "anal", "Anal" }, { "enfermeras", "Enfermeras" }, { "futanari", "Futanari" },
    { "hardcore", "Hardcore" }, { "incesto", "Incesto" }, { "milfs", "milfs" },
    { "juegos sexuales", "Juegos Sexuales" }, { "maids", "Sirvientas" },
    { "netorare", "Netorare" }, { "ninfomania", "Ninfomanía" }, { "ninjas", "Ninjas" },
    { "orgias", "Orgías" }, { "succubus", "Súcubo" }, { "teacher", "Profesoras" },
    { "tentaculos", "Tentáculos" }, { "tetonas", "Pechonas" }, { "vanilla", "Vainilla" },
    { "virgenes", "Vírgenes" }, { "bondage", "Bondage" }, { "threesome", "Trío" },
    { "elfas", "Elfas" }, { "paizuri", "Paizuri" }, { "gal", "Gal" },
    { "oyakodon", "Oyakodon" }, { "shota", "shota" }, { "petit", "petit" },
    -- Not in the CloudStream list; harmless if the site has no such slug.
    { "escolares", "Escolares" }, { "harem", "Harem" }, { "yuri", "Yuri" },
    { "yaoi", "Yaoi" }, { "ecchi", "Ecchi" }, { "romance", "Romance" },
    { "3d", "3D" }, { "gore", "Gore" },
}

local function urlDecode(s)
    s = s:gsub("%+", " ")
    s = s:gsub("%%(%x%x)", function(h) return string.char(tonumber(h, 16)) end)
    return s
end

local function titleCase(s)
    return (s:gsub("(%a)([%w]*)", function(a, b) return a:upper() .. b end))
end

local _genreCache = nil

-- Reads every genre link / checkbox on /catalogo, then merges the static list.
local function discoverGenres()
    if _genreCache then return _genreCache end

    local found, order = {}, {}
    local function add(slug, label)
        slug = string_trim(urlDecode(slug or "")):lower()
        if slug == "" or BLOCKED_GENRES[slug] or found[slug] then return end
        label = string_clean(label or "")
        if label == "" then label = titleCase(slug) end
        found[slug] = label
        table.insert(order, slug)
    end

    local r = http_get(CATALOG)
    if r.success then
        for _, a in ipairs(html_select(r.body, 'a[href*="genre="]')) do
            add(a.href:match("[?&]genre=([^&#]+)"), a.text)
        end
        for _, inp in ipairs(html_select(r.body, 'input[name="genre"]')) do
            local v = inp:attr("value")
            local lbl = inp:attr("aria-label")
            add(v, (lbl and lbl ~= "") and lbl or v)
        end
    else
        log_error("Hentaila: genre discovery failed (HTTP " .. tostring(r.code) .. ")")
    end

    for _, g in ipairs(STATIC_GENRES) do add(g[1], g[2]) end

    local options = {}
    for _, slug in ipairs(order) do
        table.insert(options, { value = slug, label = found[slug] })
    end
    table.sort(options, function(x, y) return x.label:lower() < y.label:lower() end)

    _genreCache = options
    return options
end

function getFilterList()
    ensureLibs()
    return {
        {
            type         = "select",
            key          = "order",
            label        = "Ordenar por",
            defaultValue = "latest_added",
            options = {
                { value = "latest_added",    label = "Últimos añadidos" },
                { value = "latest_released", label = "Últimos estrenados" },
            }
        },
        {
            type         = "select",
            key          = "status",
            label        = "Estado",
            defaultValue = "all",
            options = {
                { value = "all",     label = "Todos" },
                { value = "emision", label = "En emisión" },
            }
        },
        {
            type    = "checkbox",
            key     = "genre",
            label   = "Géneros",
            options = discoverGenres()
        },
    }
end

function getCatalogFiltered(index, filters)
    ensureLibs()
    if type(filters) ~= "table" then filters = {} end

    local order = filters["order"]
    if type(order) ~= "string" or order == "" then order = "latest_added" end
    local q = "?order=" .. CATLIB.urlEncode(order)

    local status = filters["status"]
    if type(status) == "string" and status ~= "" and status ~= "all" then
        q = q .. "&status=" .. CATLIB.urlEncode(status)
    end

    -- Checkbox "genre" arrives as filters["genre_included"] (array of values).
    -- Lowercased because the site only matches lowercase slugs.
    local genres = filters["genre_included"]
    if type(genres) == "table" then
        for _, g in ipairs(genres) do
            if type(g) == "string" and g ~= "" then
                q = q .. "&genre=" .. CATLIB.urlEncode(g:lower())
            end
        end
    end

    log_info("Hentaila: filtered -> " .. CATALOG .. q .. "&page=" .. CATLIB.nextIndex(index))
    return fetchCatalog(q .. "&page=" .. CATLIB.nextIndex(index))
end
